const supportedBanks = new Set(['FED', 'ECB', 'RBI']);

const output = [];

for (const item of $input.all()) {
  const statement = item.json;

  // Step 1: Basic source validation
  if (
    !statement.id ||
    !statement.central_bank ||
    !statement.content
  ) {
    continue;
  }

  // Step 2: Normalize the statement
  const normalized = {
    statement_id: String(statement.id),
    central_bank: String(statement.central_bank),
    bank_code: String(statement.bank_code || '').trim().toUpperCase(),
    country: String(statement.country || ''),
    document_type: String(statement.document_type || 'Statement'),
    title: String(statement.title || ''),
    speaker: String(statement.speaker || ''),
    published_at: statement.published_at || null,
    source_url: String(statement.url || ''),
    content: String(statement.content).trim()
  };

  // Step 3: Keep only supported central banks
  if (!supportedBanks.has(normalized.bank_code)) {
    continue;
  }

  // Step 4: Validate required fields
  if (
    !normalized.statement_id ||
    !normalized.central_bank ||
    !normalized.bank_code ||
    !normalized.content ||
    normalized.content.length < 50 ||
    !normalized.published_at
  ) {
    continue;
  }

  // Step 5: Add valid statement to output
  output.push({
    json: normalized
  });
}

return output;

const incoming = $('Normalize and Validate Statements').all().map(item => item.json);
const history = $input.all().map(item => item.json);

const processedIds = new Set(
  history
    .map(item => item.statement_id)
    .filter(Boolean)
    .map(id => String(id))
);

const seenInCurrentExecution = new Set();

return incoming
  .filter(statement => {
    const id = String(statement.statement_id);

    if (processedIds.has(id)) {
      return false;
    }

    if (seenInCurrentExecution.has(id)) {
      return false;
    }

    seenInCurrentExecution.add(id);
    return true;
  })
  .map(statement => ({ json: statement }));

return $input.all().map(item => {
  const data = item.json;

  return {
    json: {
      ...data,
      ai_input: {
        central_bank: data.central_bank,
        bank_code: data.bank_code,
        document_type: data.document_type,
        title: data.title,
        speaker: data.speaker,
        published_at: data.published_at,
        content: data.content
      }
    }
  };
});

const responses = $input.all();
const originalItems = $('Prepare Sentiment Analysis Input').all();

return responses.map((item, index) => {
  const response = item.json;
  const original = originalItems[index]?.json || {};

  let result = {};

  try {
    const content = response.choices?.[0]?.message?.content || '{}';
    result = typeof content === 'string' ? JSON.parse(content) : content;
  } catch (error) {
    result = {};
  }

  const validStances = ['hawkish', 'neutral', 'dovish'];
  const score = Number(result.sentiment_score);
  const confidence = Number(result.confidence);

  return {
    json: {
      statement_id: original.statement_id,
      central_bank: original.central_bank,
      bank_code: original.bank_code,
      country: original.country,
      document_type: original.document_type,
      title: original.title,
      speaker: original.speaker,
      published_at: original.published_at,
      source_url: original.source_url,
      stance: validStances.includes(result.stance) ? result.stance : 'neutral',
      sentiment_score: Number.isFinite(score) ? Math.max(-100, Math.min(100, score)) : 0,
      confidence: Number.isFinite(confidence) ? Math.max(0, Math.min(100, confidence)) : 0,
      key_phrase: String(result.key_phrase || ''),
      summary: String(result.summary || ''),
      policy_signal: String(result.policy_signal || ''),
      processed_at: new Date().toISOString()
    }
  };
});

const history = $input.all().map(item => item.json);

const currentRecords = $('Parse Sentiment Analysis Result')
  .all()
  .map(item => item.json);

const output = [];

for (const current of currentRecords) {
  // Find the latest 5 historical records
  // for the same central bank, excluding the current statement
  const previous = history
    .filter(record => {
      return (
        record.bank_code === current.bank_code &&
        record.statement_id !== current.statement_id &&
        record.sentiment_score !== undefined &&
        record.published_at
      );
    })
    .map(record => ({
      published_at: record.published_at,
      sentiment_score: Number(record.sentiment_score)
    }))
    .filter(record => Number.isFinite(record.sentiment_score))
    .sort(
      (a, b) =>
        new Date(b.published_at) - new Date(a.published_at)
    )
    .slice(0, 5);

  // Calculate rolling average
  const scores = previous.map(record => record.sentiment_score);

  const rollingAverage = scores.length > 0
    ? scores.reduce((sum, score) => sum + score, 0) / scores.length
    : 0;

  // Calculate current sentiment shift
  const currentScore = Number(current.sentiment_score) || 0;

  const sentimentShift = currentScore - rollingAverage;

  // Determine whether the shift is meaningful
  const meaningfulShift = Math.abs(sentimentShift) >= 20;

  // Determine shift direction
  const shiftDirection =
    sentimentShift > 0
      ? 'more_hawkish'
      : sentimentShift < 0
        ? 'more_dovish'
        : 'unchanged';

  output.push({
    json: {
      ...current,

      rolling_average: Number(
        rollingAverage.toFixed(2)
      ),

      sentiment_shift: Number(
        sentimentShift.toFixed(2)
      ),

      historical_sample_size: scores.length,

      meaningful_shift: meaningfulShift,

      shift_direction: shiftDirection
    }
  });
}

return output;

return $input.all().map(item => {
  const data = item.json;

  const direction = data.shift_direction === "more_hawkish"
    ? "More hawkish"
    : "More dovish";

  return {
    json: {
      ...data,
      slack_message:
        `Central bank sentiment shift detected\n\n` +
        `Central Bank: ${data.central_bank}\n` +
        `Direction: ${direction}\n` +
        `Current Score: ${data.sentiment_score}\n` +
        `Rolling Average: ${data.rolling_average}\n` +
        `Shift: ${data.sentiment_shift}\n` +
        `Stance: ${data.stance}\n` +
        `Confidence: ${data.confidence}%\n` +
        `Key Phrase: ${data.key_phrase}\n` +
        `Summary: ${data.summary}\n` +
        `Policy Signal: ${data.policy_signal}\n` +
        `Source: ${data.source_url}`
    }
  };
});
